properties.query:
let windowSize = 1h;

// S99: Passive Recon — 제안 스키마(미배포). UAVOpAudit_CL을 전역 게이트로 대리 사용 (SwarmId 없음)
let S99Time = toscalar(
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType in ('recon_scan','passive_scan')
    | summarize min(TimeGenerated));

// S101: Leader Hijack — UAVFleetState_CL, FleetId 사용
let S101 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where UnknownUavIdDetected == true
    | extend Stage = 'S101', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S107: 1:N Command Amplification — 단일 CommonCommand가 다수 UAV에 동시 적용
let S107 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotempty(CommonCommand) and ActiveUAVCount > 3
    | extend Stage = 'S107', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

// S104: Formation Scatter — DivergingCount 급증
let S104 =
    UAVFleetState_CL
    | where TimeGenerated > ago(windowSize)
    | where DivergingCount > 2
    | extend Stage = 'S104', SwarmId = tostring(FleetId)
    | where isnotempty(SwarmId)
    | project TimeGenerated, Stage, SwarmId;

union S101, S107, S104
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by SwarmId
| extend HasS99 = isnotnull(S99Time)
| extend EffectiveStageCount = StageCount + toint(HasS99)
| where EffectiveStageCount >= 3
| extend CampaignType = "C24_리더참수_정찰_스푸핑_증폭_분산"
| extend StepSummary = strcat("S99(전역)@", tostring(S99Time), " | Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, SwarmId, StagesSeen, EffectiveStageCount, CampaignType, StepSummary, Severity
